				if keys, ok := pkgDecls[currentPkg][name]; ok {
					for _, k := range keys {
						if !k.IsMethod {
							matched = append(matched, k)
						}
					}
				}
			case *ast.SelectorExpr:
				sel := fun.Sel.Name
				switch x := fun.X.(type) {
				case *ast.Ident:
