perl -e '
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = "/bench/repo";
my $STORE_MODULE = "github.com/usememos/memos/store";

my @ENTITY_TYPES = qw(
    Attachment IdentityProvider Inbox InstanceSetting
    Memo MemoRelation MemoShare Reaction
    User UserIdentity UserSetting
);

my %DEFINITIONS = (
    Attachment => ["store/attachment.go", 16],
    IdentityProvider => ["store/idp.go", 12],
    Inbox => ["store/inbox.go", 24],
    InstanceSetting => ["store/instance_setting.go", 14],
    Memo => ["store/memo.go", 35],
    MemoRelation => ["store/memo_relation.go", 16],
    MemoShare => ["store/memo_share.go", 6],
    Reaction => ["store/reaction.go", 7],
    User => ["store/user.go", 29],
    UserIdentity => ["store/user_identity.go", 8],
    UserSetting => ["store/user_setting.go", 13],
);

sub is_store_layer {
    my ($path) = @_;
    my $dir = dirname($path);
    my $rel = $dir;
    $rel =~ s/^\Q$REPO\E\/?//;
    return ($rel eq "store" || $rel =~ m{^store/});
}

sub package_path_from_dir {
    my ($dir) = @_;
    my $rel = $dir;
    $rel =~ s/^\Q$REPO\E\/?//;
    return "github.com/usememos/memos" if $rel eq "" || $rel eq ".";
    return "github.com/usememos/memos/$rel";
}

sub parse_import_alias {
    my ($content) = @_;
    my %aliases;
    while ($content =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        my $base = (split /\//, $path)[-1];
        $aliases{$path} = $base;
    }
    while ($content =~ /import\s*\((.*?)\)/gs) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/^\s+|\s+$//g;
            next if $line eq "" || $line =~ /^\/\//;
            if ($line =~ /^(\w+)\s+"([^"]+)"/) {
                $aliases{$2} = $1;
            } elsif ($line =~ /^"([^"]+)"/) {
                my $path = $1;
                my $base = (split /\//, $path)[-1];
                $aliases{$path} = $base;
            }
        }
    }
    return \%aliases;
}

sub go_package_name {
    my ($content) = @_;
    return $1 if $content =~ /^package\s+(\w+)/m;
    return undef;
}

my @all_go_files;
find(sub {
    return unless -f && /\.go$/;
    push @all_go_files, $File::Find::name;
}, $REPO);

# refs: entity -> pkg -> hash of file:line
my (%refs_with, %refs_no);
for my $e (@ENTITY_TYPES) {
    $refs_with{$e} = {};
    $refs_no{$e} = {};
}

for my $path (@all_go_files) {
    next if is_store_layer($path);
    open my $fh, "<", $path or next;
    my $content = do { local $/; <$fh> };
    close $fh;

    my $aliases = parse_import_alias($content);
    my $store_alias = $aliases->{$STORE_MODULE};
    next unless defined $store_alias;

    my $pkg_path = package_path_from_dir(dirname($path));
    my $pkg_name = go_package_name($content);
    my $is_test = ($path =~ /_test\.go$/) || (defined $pkg_name && $pkg_name =~ /_test$/);
    my $rel_path = $path;
    $rel_path =~ s/^\Q$REPO\E\/?//;

    my $i = 0;
    for my $line (split /\n/, $content) {
        $i++;
